"""Read ids.txt and print the next order id (ORD- followed by four base36 chars)."""

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer as a zero-padded base36 string of the given width."""
    digits = []
    for _ in range(width):
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def base36_decode(s: str) -> int:
    """Decode a base36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch)
    return n


def next_id(last_id: str) -> str:
    """Given an id like 'ORD-243G', return the next id."""
    prefix, suffix = last_id.rsplit("-", 1)
    n = base36_decode(suffix)
    n += 1
    if n >= 36 ** 4:
        print("error: id overflow", file=sys.stderr)
        sys.exit(1)
    return f"{prefix}-{base36_encode(n)}"


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        # Start from the beginning
        last = "ORD-" + base36_encode(0)
    else:
        last = lines[-1]

    print(next_id(last))


if __name__ == "__main__":
    main()

