#!/usr/bin/env python3

import sys

ALPHABET = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
BASE = len(ALPHABET)  # 36

def base36_decode(s: str) -> int:
    """Decode a base36 string to an integer."""
    n = 0
    for ch in s:
        n = n * BASE + ALPHABET.index(ch)
    return n

def base36_encode(n: int) -> str:
    """Encode an integer to a base36 string."""
    if n == 0:
        return ALPHABET[0]
    chars = []
    while n > 0:
        chars.append(ALPHABET[n % BASE])
        n //= BASE
    return ''.join(reversed(chars))

def main():
    # Read ids.txt, get the last id (most recent)
    with open('ids.txt') as f:
        lines = f.read().strip().splitlines()

    if not lines:
        print('ORD-0000')
        return

    last_line = lines[-1].strip()
    if not last_line:
        print('ORD-0000')
        return

    # Extract the 4-character suffix after 'ORD-'
    prefix = 'ORD-'
    if last_line.startswith(prefix):
        suffix = last_line[len(prefix):]
    else:
        suffix = last_line

    # Decode, increment, encode
    num = base36_decode(suffix)
    num += 1
    next_suffix = base36_encode(num).rjust(4, '0')

    print(f'{prefix}{next_suffix}')

if __name__ == '__main__':
    main()

