import sys

def base36_encode(n: int) -> str:
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = ""
    for _ in range(4):
        result = chars[n % 36] + result
        n //= 36
    return result

def base36_decode(s: str) -> int:
    return int(s, 36)

def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        lines = []

    if not lines:
        # No IDs issued yet; start from ORD-0000
        suffix = "0000"
    else:
        last_line = lines[-1]
        if not last_line.startswith("ORD-"):
            print(f"Invalid id format: {last_line}", file=sys.stderr)
