"""Print the next order id by reading ids.txt (one per line, most recent last)."""

import sys


def base36_increment(s: str) -> str:
    """Increment a base-36 string by 1, preserving width."""
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        c = chars[i]
        if "0" <= c <= "8":
            chars[i] = chr(ord(c) + 1)
            return "".join(chars)
        if c == "9":
            chars[i] = "A"
            return "".join(chars)
        if "A" <= c <= "Y":
            chars[i] = chr(ord(c) + 1)
            return "".join(chars)
        # c is 'Z' — carry over
        chars[i] = "0"
    # All digits wrapped: prepend a '1' (or raise)
    return "1" + "".join(chars)


def main() -> None:
    prefix = "ORD-"
    suffix_len = 4

    try:
        with open("ids.txt", encoding="utf-8") as fh:
            lines = [line.strip() for line in fh if line.strip()]
    except FileNotFoundError:
        print(f"{prefix}{'0' * suffix_len}")
        return

    if not lines:
        print(f"{prefix}{'0' * suffix_len}")
        return

    last_id = lines[-1]
    if not last_id.startswith(prefix):
        print(f"error: unexpected id format {last_id!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[len(prefix):]
    next_suffix = base36_increment(suffix)
    print(f"{prefix}{next_suffix}")


if __name__ == "__main__":
    main()

