import sys

ID_PREFIX = "ORD-"
ID_WIDTH = 4  # characters after the prefix
BASE = 36


def base36_encode(n: int, width: int) -> str:
    chars = []
    for _ in range(width):
        n, rem = divmod(n, BASE)
        if rem < 10:
            chars.append(chr(ord("0") + rem))
        else:
            chars.append(chr(ord("A") + rem - 10))
    return "".join(reversed(chars))


def base36_decode(s: str) -> int:
    n = 0
    for ch in s:
        if "0" <= ch <= "9":
            n = n * BASE + (ord(ch) - ord("0"))
        else:
            n = n * BASE + (ord(ch) - ord("A") + 10)
    return n


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print(f"{ID_PREFIX}{base36_encode(0, ID_WIDTH)}")
        return

    if not lines:
        print(f"{ID_PREFIX}{base36_encode(0, ID_WIDTH)}")
        return

    last_line = lines[-1]
    suffix = last_line[len(ID_PREFIX):]
    current = base36_decode(suffix)
    next_id = base36_encode(current + 1, ID_WIDTH)
    print(f"{ID_PREFIX}{next_id}")


if __name__ == "__main__":
