"""Validate orders.json before the nightly billing run."""

import json
import sys


def main():
    with open("orders.json", encoding="utf-8") as handle:
        orders = json.load(handle)

    has_errors = False
    for order in orders:
        order_id = order.get("id", "")
        amount = order.get("amount", 0)
        issues = []

        if not order_id:
            issues.append("empty id")
        if amount is None or (isinstance(amount, (int, float)) and amount <= 0):
            issues.append("amount not greater than zero")

        if issues:
            has_errors = True
            print(f"{order_id}: {', '.join(issues)}")

    if has_errors:
        sys.exit(1)


if __name__ == "__main__":
    main()

