import json
import sys

def main():
    try:
        with open("orders.json") as f:
            orders = json.load(f)
    except FileNotFoundError:
        print("Error: orders.json not found", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Error: orders.json is not valid JSON: {e}", file=sys.stderr)
        sys.exit(1)

    if not isinstance(orders, list):
        print("Error: orders.json must contain a JSON array", file=sys.stderr)
        sys.exit(1)

    found_problem = False

    for i, order in enumerate(orders, start=1):
        if not isinstance(order, dict):
            print(f"order #{i}: not a JSON object")
            found_problem = True
            continue

        order_id = order.get("id")
        amount = order.get("amount")

        # Check for missing or empty id
        if order_id is None or order_id == "":
            label = str(order_id) if order_id is not None else "missing"
            print(f"order #{i}: id is {label}")
            found_problem = True

        # Check amount (must exist and be > 0)
        if amount is None:
            print(f"order #{i} [{order_id}]: amount is missing")
            found_problem = True
        elif not isinstance(amount, (int, float)):
            print(f"order #{i} [{order_id}]: amount is not a number")
            found_problem = True
        elif amount <= 0:
            print(f"order #{i} [{order_id}]: amount is {amount} (must be > 0)")
            found_problem = True

    if not found_problem:
        print("All orders are valid.")

if __name__ == "__main__":
    main()

