#!/usr/bin/env python3
"""Read events.jsonl, remove duplicates sharing an event_id, write deduped.jsonl."""

import json

def main():
    seen = set()
    with open("events.jsonl", "r") as infile, open("deduped.jsonl", "w") as outfile:
        for line in infile:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid and eid not in seen:
