import json


def load(path):
    with open(path, encoding='utf-8') as handle:
        return [json.loads(line) for line in handle if line.strip()]


def dedupe(rows):
    seen = set()
    unique = []
    for row in rows:
        event_id = row.get('event_id')
        if event_id in seen:
            continue
        seen.add(event_id)
        unique.append(row)
    return unique


def main():
    rows = load('events.jsonl')
    with open('deduped.jsonl', 'w', encoding='utf-8') as handle:
        for row in dedupe(rows):
            handle.write(json.dumps(row) + '\n')


if __name__ == '__main__':
    main()
EOF

