"""Read every .txt file in inbox/ and write report.txt with entries, total, and average."""

import glob
import os

INBOX_DIR = "inbox"


def main() -> None:
    measurements: list[int] = []

    for txt_path in sorted(glob.glob(os.path.join(INBOX_DIR, "*.txt"))):
        with open(txt_path) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                # Each line has the format: number<TAB>value
                parts = line.split("\t")
                if len(parts) >= 2:
                    value_str = parts[1].strip()
                    if value_str:
                        try:
                            measurements.append(int(value_str))
                        except ValueError:
                            pass

    entries = len(measurements)
    total = sum(measurements)
    average = total / entries if entries > 0 else 0.0

    with open("report.txt", "w") as out:
        out.write(f"entries {entries}\n")
        out.write(f"total {total}\n")
        out.write(f"average {average:.2f}\n")


if __name__ == "__main__":
    main()

