"""register.py — register a release version in releases.log.

Reads the version string from VERSION and appends it to releases.log
(one version per line).  Skips the write if the version is already
present, so that re-running the pipeline for the same version (which
can happen when the artefact upload times out) does not create
duplicate entries.
"""

import pathlib

ROOT = pathlib.Path(__file__).resolve().parent
VERSION_FILE = ROOT / "VERSION"
RELEASES_FILE = ROOT / "releases.log"


def load_version(path: pathlib.Path) -> str:
    return path.read_text().strip()


def load_releases(path: pathlib.Path) -> set[str]:
    if not path.exists():
        return set()
    return {line.strip() for line in path.read_text().splitlines() if line.strip()}


def main() -> None:
    version = load_version(VERSION_FILE)
    releases = load_releases(RELEASES_FILE)

    if version in releases:
        print(f"Version {version} already registered — skipping.")
        return

    with open(RELEASES_FILE, "a") as f:
        f.write(f"{version}\n")

    print(f"Registered version {version}.")


if __name__ == "__main__":
    main()

