"""Register the current version in releases.log.

Called after a successful artefact upload.  Idempotent: if the version
from VERSION is already recorded, this is a no-op so that re-running
the pipeline after a timeout does not produce duplicates.
"""

import pathlib


def read_version(path: str = "VERSION") -> str:
    """Return the version string from *path*, stripped."""
    return pathlib.Path(path).read_text(encoding="utf-8").strip()


def read_releases(path: str = "releases.log") -> set[str]:
    """Return the set of versions already recorded in *path*."""
    try:
        text = pathlib.Path(path).read_text(encoding="utf-8")
    except FileNotFoundError:
        return set()
    return {line.strip() for line in text.splitlines() if line.strip()}


def register(version: str, releases_path: str = "releases.log") -> bool:
    """Append *version* to *releases_path* if not already present.

    Returns True when a new entry was added, False when it already existed.
    """
    releases = read_releases(releases_path)
    if version in releases:
        return False

    with open(releases_path, "a", encoding="utf-8") as f:
        f.write(f"{version}\n")
    return True


def main() -> None:
    version = read_version()
    added = register(version)
    if added:
        print(f"Registered {version}")
    else:
        print(f"{version} already registered, skipping")


if __name__ == "__main__":
    main()

