#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> None:
    manifest = {}

    for p in sorted(RELEASE_DIR.rglob("*")):
        if not p.is_file():
            continue
        # Store path relative to repo root, using forward slashes (JSON convention)
        rel = str(p.relative_to(RELEASE_DIR.parent).as_posix())
        manifest[rel] = sha256_digest(p)

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"Wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

