"""Build manifest.json: maps each file under release/ to its SHA-256 hex digest."""

import hashlib
import json
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent
RELEASE_DIR = REPO_ROOT / "release"
MANIFEST_PATH = REPO_ROOT / "manifest.json"


def sha256_digest(path: Path) -> str:
    """Return the SHA-256 hex digest of *path*."""
    h = hashlib.sha256()
    with path.open("rb") as f:
        while True:
            block = f.read(65536)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def main() -> None:
    manifest = {}
    # Walk release/ in sorted order for deterministic output.
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            relative = path.relative_to(REPO_ROOT).as_posix()
            manifest[relative] = sha256_digest(path)

    with MANIFEST_PATH.open("w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

