"""Print report file names in report order (natural numeric sort)."""

import os
import re

REPORTS_DIR = "reports"


def report_number(filename: str) -> int:
    """Extract the numeric report number from a filename like 'report-1.txt'."""
    m = re.search(r"\d+", filename)
    if m is None:
        return 0
    return int(m.group())


def main() -> None:
    try:
        files = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"error: '{REPORTS_DIR}' directory not found")
        return

    report_files = [f for f in files if f.startswith("report-") and f.endswith(".txt")]
    report_files.sort(key=report_number)

    for f in report_files:
        print(f)


if __name__ == "__main__":
    main()

