"""Print reports/ filenames one per line, in report order."""

import os
import re

REPORTS_DIR = "reports"


def report_key(filename: str) -> int:
    """Extract the integer n from report-<n>.txt for numerical sorting."""
    match = re.match(r"report-(\d+)\.txt", filename)
    if match is None:
        # Push non-matching names to the end (shouldn't happen in practice).
        return float("inf")
    return int(match.group(1))


def main() -> None:
    try:
        names = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"error: {REPORTS_DIR}/ not found", file=__import__("sys").stderr)
        __import__("sys").exit(1)

    # Filter to only the expected report files and sort numerically.
    report_files = [n for n in names if re.match(r"report-\d+\.txt", n)]
    report_files.sort(key=report_key)

    for name in report_files:
        print(name)


if __name__ == "__main__":
    main()

