import os
import glob
from collections import Counter

def main():
    counter = Counter()
    punctuations = set(".,;:!?")

    for filepath in glob.glob("docs/**/*.txt", recursive=True):
        if not os.path.isfile(filepath):
            continue
        with open(filepath, "r", encoding="utf-8") as f:
            for line in f:
                words = line.split()
                for word in words:
                    # Lowercase
                    word = word.lower()
                    # Strip punctuation from edges
                    word = word.strip("".join(punctuations))
                    if word:
                        counter[word] += 1

    with open("counts.txt", "w", encoding="utf-8") as out:
        for word in sorted(counter):
            out.write(f"{word} {counter[word]}\n")

if __name__ == "__main__":
    main()

