#!/usr/bin/env python3
"""Count word frequencies in all .txt files under docs/."""

import re
from collections import Counter
from pathlib import Path

PUNCTUATION = '.,;:!?'

def words_from_file(path):
    """Yield lowercased words from a file, stripped of edge punctuation."""
    text = path.read_text(encoding='utf-8')
    for word in text.split():
        word = word.lower().strip(PUNCTUATION)
        if word:
            yield word


def main():
    root = Path('.')
    counter = Counter()

    for txt_file in sorted(root.glob('docs/**/*.txt')):
        for word in words_from_file(txt_file):
            counter[word] += 1

    out_path = root / 'counts.txt'
    with open(out_path, 'w', encoding='utf-8') as f:
        for word in sorted(counter):
            f.write(f'{word} {counter[word]}\n')


if __name__ == '__main__':
    main()

