#!/usr/bin/env python3
"""Count word occurrences in every .txt file under docs/.

Words are lowercased and the punctuation characters .,;:!? are stripped
from word edges before counting. Results are written to counts.txt,
one ``word count`` per line, sorted alphabetically by word.
"""

from collections import Counter
from pathlib import Path

PUNCTUATION = ".,;:!?"


def iter_words(docs_dir):
    """Yield cleaned words from every .txt file under docs_dir."""
    for txt_path in sorted(docs_dir.rglob("*.txt")):
        if not txt_path.is_file():
            continue
        for line in txt_path.read_text(encoding="utf-8").splitlines():
            for raw_word in line.split():
                word = raw_word.strip(PUNCTUATION).lower()
                if word:
                    yield word


def main():
    docs_dir = Path("docs")
    counts = Counter(iter_words(docs_dir))

    output_path = Path("counts.txt")
    with output_path.open("w", encoding="utf-8") as out:
        for word in sorted(counts):
            out.write(f"{word} {counts[word]}\n")


if __name__ == "__main__":
    main()

