#!/usr/bin/env python3
"""Count word occurrences in every .txt file under docs/."""

import os
import re
import unicodedata
from collections import Counter

DOCS_DIR = "docs"
OUTPUT_FILE = "counts.txt"
PUNCTUATION = set(".,;:!?")
TXT_EXTENSION = ".txt"


def tokenize(text: str) -> list[str]:
    """Normalise to NFC, lowercase, split on whitespace, strip edge punctuation."""
    text = unicodedata.normalize("NFC", text)
    words = text.lower().split()
    result = []
    for w in words:
        w = w.strip("".join(PUNCTUATION))
        if w:
            result.append(w)
    return result


def main() -> None:
    counter: Counter[str] = Counter()
    txt_files = [
        os.path.join(DOCS_DIR, f)
        for f in sorted(os.listdir(DOCS_DIR))
        if f.endswith(TXT_EXTENSION)
    ]

    for path in txt_files:
        with open(path, encoding="utf-8") as fh:
            text = fh.read()
        for word in tokenize(text):
            counter[word] += 1

    with open(OUTPUT_FILE, "w", encoding="utf-8") as fh:
        for word in sorted(counter):
            fh.write(f"{word} {counter[word]}\n")


if __name__ == "__main__":
    main()

