#!/usr/bin/env python3
"""Count word frequencies in .txt files under docs/."""

import glob
import os
from collections import Counter

PUNCTUATION = set(".,;:!?")

def strip_punctuation(word):
    """Strip punctuation characters from the edges of a word."""
    while word and word[0] in PUNCTUATION:
        word = word[1:]
    while word and word[-1] in PUNCTUATION:
        word = word[:-1]
    return word

def main():
    counter = Counter()

    # Find all .txt files under docs/ (recursively)
    txt_files = glob.glob("docs/**/*.txt", recursive=True)

    for filepath in txt_files:
        with open(filepath, encoding="utf-8") as f:
            for line in f:
                for raw_word in line.split():
                    word = strip_punctuation(raw_word).lower()
                    if word:  # skip empty strings
                        counter[word] += 1

    # Write sorted output
    with open("counts.txt", "w", encoding="utf-8") as out:
        for word in sorted(counter):
            out.write(f"{word} {counter[word]}\n")

if __name__ == "__main__":
    main()

