import time


class TransportError(Exception):
    """Raised by a transport when a fetch attempt fails."""


def fetch(url, transport, sleep=time.sleep):
    """Fetch ``url`` via ``transport``, retrying with jittered exponential backoff."""
    max_attempts = 8
    base_delay = 1.0          # seconds
    max_delay = 30.0          # seconds -- never sleep longer than this

    for attempt in range(1, max_attempts + 1):
        try:
            return transport(url)
        except TransportError:
            if attempt == max_attempts:
                raise
            cap = min(base_delay * (2 ** (attempt - 1)), max_delay)
            delay = random.uniform(0, cap)
            sleep(delay)

