#!/usr/bin/env python3
"""Rotate old entries from app.log to archive.log."""

import sys
import datetime


def parse_timestamp(line: str):
    """Parse YYYY-MM-DD HH:MM:SS from start of line, return (datetime, rest)."""
    ts_str = line[:19]
    dt = datetime.datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S")
    return dt.replace(tzinfo=datetime.timezone.utc), line[19:]


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff = as_of - 7 * 24 * 3600  # strictly older than 7 days before AS_OF

    with open("app.log", "r") as f:
        lines = f.readlines()

    kept = []
    archived = []

    for line in lines:
        # Skip empty lines
        if line.strip() == "":
            continue
        dt, _ = parse_timestamp(line)
        ts = int(dt.timestamp())
        if ts < cutoff:
            archived.append(line)
        else:
            kept.append(line)

    # Append archived entries to archive.log (preserving order)
    if archived:
        with open("archive.log", "a") as f:
            for entry in archived:
                f.write(entry)

    # Rewrite app.log with kept entries
    with open("app.log", "w") as f:
        for entry in kept:
            f.write(entry)


if __name__ == "__main__":
    main()

